-- اعضا، دعوت‌نامه، وظایف، زمان کاری و اعلان‌ها
create table if not exists public.employees(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid references auth.users(id) on delete set null,name text not null,email text,role text not null default 'employee',created_at timestamptz not null default now());
create table if not exists public.workspace_invitations(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,email text not null,role text not null default 'employee',created_at timestamptz not null default now(),unique(workspace_id,email));
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,title text not null,description text,assignee_id uuid references public.employees(id) on delete set null,due_at timestamptz,status text not null default 'todo' check(status in ('todo','in_progress','done')),created_at timestamptz not null default now());
create table if not exists public.work_hours(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,employee_id uuid not null references public.employees(id) on delete cascade,started_at timestamptz not null default now(),ended_at timestamptz,check(ended_at is null or ended_at>=started_at));
create table if not exists public.notifications(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,title text not null,body text,read_at timestamptz,created_at timestamptz not null default now());